import java.nio.file.Files;
import java.nio.file.Path;

public class LineCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        Path file = Files.createTempFile("linecounter-test", ".txt");
        try {
            Files.writeString(file, "alpha\n\nbeta\n   \ngamma\n");
            check("mixed content with blank lines", 3, LineCounter.countNonBlankLines(file));
            Files.writeString(file, "");
            check("empty file", 0, LineCounter.countNonBlankLines(file));
            Files.writeString(file, "   \n\t\n  \n");
            check("whitespace-only lines", 0, LineCounter.countNonBlankLines(file));
            Files.writeString(file, "one\ntwo");
            check("no trailing newline", 2, LineCounter.countNonBlankLines(file));
            Files.writeString(file, "solo\n");
            check("single line", 1, LineCounter.countNonBlankLines(file));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        } finally {
            Files.deleteIfExists(file);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

